node --input-type=module -e "
import { MAP_ROWS, createWorld } from './js/world.js';
const bad = MAP_ROWS.map((r,i)=>[i,r.length]).filter(([,l])=>l!==32);
console.log('rows', MAP_ROWS.length, 'bad', bad);
