   e.pathTimer -= dt;
   if(e.pathTimer<=0 || !e.path.length){
     e.path = world.findPath(e.x,e.y,player.x,player.y);
     e.pathTimer=0.65+Math.random()*0.4;
   }
   const node=e.path[0];
   if(node){
     const ndx=node.x-e.x, ndy=node.y-e.y; const nd=Math.hypot(ndx,ndy);
     if(nd<0.22) e.path.shift();
     else { mx=ndx/nd; my=ndy/nd; }
   }
