   else if(los && dist>7) { e.strafe*=-1; e.strafeTimer=1.5; }
   if(!world.circleBlocked(e.x,e.y+ny,0.3)) e.y+=ny;
   e.moving = true;
   e.walkPhase += dt*sp*1.6;
 }
 // keep min distance from player
 if(dist<1.05){ push away }
