// CS:GO 1.6 — browser FPS built on a tiny raycasting engine.

import { Renderer } from './renderer.js';
import { createWorld } from './world.js';
import { AudioEngine } from './audio.js';
import {
  WEAPONS,
  WEAPON_ORDER,
  makeLoadout,
  startReload,
  switchWeapon,
  updateWeapon,
  tryShoot,
  updateEnemies,
  spawnEnemies,
} from './combat.js';

const $ = (id) => document.getElementById(id);
const canvas = $('view');
const renderer = new Renderer(canvas);
const world = createWorld();
const audio = new AudioEngine();
const touchUI =
  window.matchMedia('(pointer: coarse)').matches ||
  navigator.maxTouchPoints > 0 ||
  window.innerWidth < 820;

function makePlayer() {
  return {
    x: world.spawn.x,
    y: world.spawn.y,
    angle: world.spawn.angle,
    pitch: 0,
    health: 100,
    armor: 100,
    weapon: 'ak',
    weapons: makeLoadout(),
    cooldown: 0,
    reloading: 0,
    reloadTotal: 0,
    recoil: 0,
    flash: 0,
    swing: 0,
    crouch: false,
    moving: false,
    bob: 0,
    sway: 0,
  };
}

const game = {
  state: 'menu',
  time: 0,
  round: 1,
  roundTime: 105,
  roundActive: false,
  transition: 0,
  roundStartDelay: 0,
  kills: 0,
  headshots: 0,
  shots: 0,
  hits: 0,
  money: 800,
  enemies: [],
  particles: [],
  viewH: renderer.H,
  player: makePlayer(),
  firing: false,
  fireEdge: false,
  shake: 0,
  hurt: 0,
  muzzle: 0,
  hitmarker: 0,
  hitmarkerHead: false,
  bobPhase: 0,
  stepTimer: 0,
  bannerTimer: 0,
  deathTimer: 0,
  hintTimer: 7,
  autoReload: 0,
};

game.damagePlayer = (amount, source) => {
  if (game.state !== 'playing') return;
  const p = game.player;
  let dmg = amount;
  if (p.armor > 0) {
    const absorbed = Math.min(p.armor, dmg * 0.5);
    p.armor -= absorbed;
    dmg -= absorbed;
  }
  p.health -= dmg;
  game.hurt = Math.min(1, game.hurt + 0.55);
  game.shake = Math.max(game.shake, 3.2);
  audio.hurt();
  if (p.health <= 0) {
    p.health = 0;
    die(source);
  }
};

game.onEnemyKilled = (enemy, head) => {
  addKillFeed(enemy, head);
  if (game.roundActive && game.enemies.every((e) => !e.alive)) roundWon();
};

// ---------- element refs ----------

const el = {
  hud: $('hud'),
  menu: $('menu'),
  pause: $('pause'),
  gameover: $('gameover'),
  touch: $('touch'),
  health: $('health'),
  armor: $('armor'),
  money: $('money'),
  ammoNow: $('ammoNow'),
  ammoReserve: $('ammoReserve'),
  weaponName: $('weaponName'),
  ammo: $('ammo'),
  vitals: $('vitals'),
  timer: $('timer'),
  roundLabel: $('roundLabel'),
  enemyCount: $('enemyCount'),
  crosshair: $('crosshair'),
  hitmarker: $('hitmarker'),
  damage: $('damage'),
  lowhp: $('lowhp'),
  banner: $('banner'),
  bannerTitle: $('bannerTitle'),
  bannerSub: $('bannerSub'),
  killfeed: $('killfeed'),
  radar: $('radar'),
  hint: $('hint'),
  goTitle: $('goTitle'),
  goReason: $('goReason'),
  goKills: $('goKills'),
  goHeads: $('goHeads'),
  goAcc: $('goAcc'),
  goRound: $('goRound'),
  goMoney: $('goMoney'),
  menuBestKills: $('menuBestKills'),
  menuBestRound: $('menuBestRound'),
  menuBestAcc: $('menuBestAcc'),
  soundBtn: $('soundBtn'),
  pauseSoundBtn: $('pauseSoundBtn'),
  roundstate: $('roundstate'),
};

const radarCtx = el.radar.getContext('2d');
const textCache = new Map();

function setText(key, node, value) {
  if (textCache.get(key) === value) return;
  textCache.set(key, value);
  node.textContent = value;
}

function show(node) {
  node.classList.remove('hidden');
}

function hide(node) {
  node.classList.add('hidden');
}

let soundMuted = false;
try {
  soundMuted = localStorage.getItem('cs16-muted') === '1';
} catch {}
audio.setMuted(soundMuted);

function updateSoundLabels() {
  const label = soundMuted ? 'ЗВУК: ВЫКЛ' : 'ЗВУК: ВКЛ';
  el.soundBtn.textContent = label;
  el.pauseSoundBtn.textContent = label;
}

function toggleSound() {
  soundMuted = !soundMuted;
  audio.init();
  audio.setMuted(soundMuted);
  try {
    localStorage.setItem('cs16-muted', soundMuted ? '1' : '0');
  } catch {}
  updateSoundLabels();
  if (!soundMuted) audio.ui();
}

function readBest() {
  try {
    return JSON.parse(localStorage.getItem('cs16-best') || '{}');
  } catch {
    return {};
  }
}

function saveBest() {
  const best = readBest();
  const acc = game.shots ? Math.round((game.hits / game.shots) * 100) : 0;
  best.kills = Math.max(best.kills || 0, game.kills);
  best.round = Math.max(best.round || 0, game.round);
  best.acc = Math.max(best.acc || 0, acc);
  try {
    localStorage.setItem('cs16-best', JSON.stringify(best));
  } catch {}
  updateMenuBest();
}

function updateMenuBest() {
  const best = readBest();
  setText('bk', el.menuBestKills, String(best.kills || 0));
  setText('br', el.menuBestRound, String(best.round || 0));
  setText('ba', el.menuBestAcc, `${best.acc || 0}%`);
}

function banner(title, sub, seconds = 2.2) {
  el.bannerTitle.textContent = title;
  el.bannerSub.textContent = sub;
  el.banner.classList.add('show');
  game.bannerTimer = seconds;
}

function addKillFeed(enemy, head) {
  const row = document.createElement('div');
  row.className = 'kf';
  const you = document.createElement('b');
  you.textContent = 'ВЫ';
  const arrow = document.createElement('span');
  arrow.textContent = '▸';
  const name = document.createElement('span');
  name.textContent = enemy.name;
  row.append(you, arrow, name);
  if (head) {
    const hs = document.createElement('span');
    hs.className = 'hs';
    hs.textContent = '★ HS';
    row.append(hs);
  }
  el.killfeed.appendChild(row);
  while (el.killfeed.children.length > 5) el.killfeed.firstElementChild.remove();
  setTimeout(() => {
    row.classList.add('out');
    setTimeout(() => row.remove(), 420);
  }, 3800);
}

function fmtTime(seconds) {
  const s = Math.max(0, Math.ceil(seconds));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

function updateHUD() {
  const p = game.player;
  setText('hp', el.health, String(Math.max(0, Math.ceil(p.health))));
  setText('ap', el.armor, String(Math.max(0, Math.ceil(p.armor))));
  setText('money', el.money, '$' + game.money);
  setText('timer', el.timer, fmtTime(game.roundTime));
  setText('round', el.roundLabel, `РАУНД ${game.round}`);
  const alive = game.enemies.filter((e) => e.alive).length;
  setText('enemies', el.enemyCount, `T: ${alive}`);
  setText('weapon', el.weaponName, WEAPONS[p.weapon].name);
  const st = p.weapons[p.weapon];
  if (p.weapon === 'knife') {
    setText('ammo', el.ammoNow, '∞');
    setText('reserve', el.ammoReserve, '');
  } else {
    setText('ammo', el.ammoNow, String(st.ammo));
    setText('reserve', el.ammoReserve, String(st.reserve));
  }
  el.ammo.classList.toggle('low', p.weapon !== 'knife' && st.ammo <= Math.ceil(WEAPONS[p.weapon].mag * 0.25));
  el.health.parentElement.classList.toggle('low', p.health <= 30);
  el.armor.parentElement.classList.toggle('low', p.armor <= 0);
  el.timer.classList.toggle('low', game.roundTime <= 15 && game.roundActive);
  el.lowhp.classList.toggle('on', p.health > 0 && p.health <= 30);

  const spread = 5 + p.recoil * 13 + (p.moving ? 4 : 0) + (p.crouch ? -1 : 0);
  el.crosshair.style.setProperty('--gap', `${spread.toFixed(1)}px`);

  el.hitmarker.style.opacity = String(Math.min(1, game.hitmarker * 7));
  el.hitmarker.classList.toggle('head', game.hitmarkerHead);
  el.damage.style.opacity = String(Math.min(0.85, game.hurt));
  el.roundstate.textContent = p.reloading > 0 ? 'ПЕРЕЗАРЯДКА…' : '';
  el.roundstate.classList.toggle('hidden', p.reloading <= 0);
}

function drawRadar() {
  const ctx = radarCtx;
  const S = 160;
  ctx.clearRect(0, 0, S, S);
  const scale = Math.min((S - 12) / world.w, (S - 12) / world.h);
  const ox = (S - world.w * scale) / 2;
  const oy = (S - world.h * scale) / 2;
  ctx.fillStyle = 'rgba(22,24,18,0.55)';
  ctx.fillRect(0, 0, S, S);

  for (let y = 0; y < world.h; y++) {
    for (let x = 0; x < world.w; x++) {
      const t = world.grid[y * world.w + x];
      if (!t) continue;
      ctx.fillStyle = t === 2 ? 'rgba(168,124,64,0.85)' : 'rgba(120,108,82,0.7)';
      ctx.fillRect(ox + x * scale, oy + y * scale, Math.ceil(scale), Math.ceil(scale));
    }
  }

  const p = game.player;
  const px = ox + p.x * scale;
  const py = oy + p.y * scale;
  // fov wedge
  ctx.save();
  ctx.translate(px, py);
  ctx.rotate(p.angle);
  const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 24);
  grad.addColorStop(0, 'rgba(245,165,36,0.22)');
  grad.addColorStop(1, 'rgba(245,165,36,0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.arc(0, 0, 24, -0.55, 0.55);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#ffd37a';
  ctx.beginPath();
  ctx.moveTo(6, 0);
  ctx.lineTo(-4, 4);
  ctx.lineTo(-2, 0);
  ctx.lineTo(-4, -4);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  for (const e of game.enemies) {
    if (!e.alive) continue;
    const d = Math.hypot(e.x - p.x, e.y - p.y);
    const visible = d < 22 && (world.lineOfSight(p.x, p.y, e.x, e.y) || e.alerted);
    if (!visible) continue;
    ctx.fillStyle = '#ff5a4a';
    ctx.beginPath();
    ctx.arc(ox + e.x * scale, oy + e.y * scale, 2.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,90,74,0.3)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(ox + e.x * scale, oy + e.y * scale, 4.5, 0, Math.PI * 2);
    ctx.stroke();
  }
}

function startGame() {
  audio.init();
  audio.setMuted(soundMuted);
  audio.resume();
  resetGame();
  hide(el.menu);
  hide(el.gameover);
  hide(el.pause);
  show(el.hud);
  if (touchUI) show(el.touch);
  document.body.classList.add('in-game');
  document.body.classList.remove('menu-open');
  el.hint.classList.remove('fade');
  game.hintTimer = 7;
  startRound(1);
  updateHUD();
  if (!touchUI) lockPointer();
}

function resetGame() {
  game.state = 'playing';
  game.round = 1;
  game.roundTime = 105;
  game.roundActive = false;
  game.transition = 0;
  game.kills = 0;
  game.headshots = 0;
  game.shots = 0;
  game.hits = 0;
  game.money = 800;
  game.player = makePlayer();
  game.enemies = [];
  game.particles = [];
  game.firing = false;
  game.fireEdge = false;
  game.shake = 0;
  game.hurt = 0;
  game.muzzle = 0;
  game.hitmarker = 0;
  game.bannerTimer = 0;
  game.deathTimer = 0;
  game.autoReload = 0;
  el.killfeed.innerHTML = '';
  el.banner.classList.remove('show');
}

function startRound(n) {
  const p = game.player;
  game.round = n;
  game.roundTime = 105;
  game.roundActive = false;
  game.roundStartDelay = 1.15;
  game.transition = 0;
  game.firing = false;
  game.fireEdge = false;
  game.particles = [];
  p.health = 100;
  p.armor = 100;
  p.weapons = makeLoadout();
  p.weapon = 'ak';
  p.x = world.spawn.x;
  p.y = world.spawn.y;
  p.angle = world.spawn.angle;
  p.pitch = 0;
  p.cooldown = 0;
  p.reloading = 0;
  p.reloadTotal = 0;
  p.recoil = 0;
  p.flash = 0;
  p.swing = 0;
  p.bob = 0;
  p.sway = 0;
  game.bobPhase = 0;
  game.enemies = spawnEnemies(world, p, Math.min(3 + n, 9), renderer.tex.enemies);
  banner(
    n === 1 ? 'РАУНД 1' : `РАУНД ${n}`,
    n === 1 ? 'УСТРАНИТЕ ВСЕХ ТЕРРОРИСТОВ' : `ТЕРРОРИСТОВ: ${game.enemies.length}`,
    2.1
  );
  audio.roundStart();
  updateHUD();
}

function roundWon() {
  game.roundActive = false;
  game.transition = 2.7;
  game.money += 2500;
  saveBest();
  banner('РАУНД ВЫИГРАН', '+$2500 · СЛЕДУЮЩИЙ РАУНД', 2.5);
  audio.win();
  game.firing = false;
}

function die() {
  if (game.state !== 'playing') return;
  game.state = 'dead';
  game.deathTimer = 0.9;
  game.roundActive = false;
  game.firing = false;
  saveBest();
  audio.lose();
  hide(el.touch);
  document.body.classList.remove('in-game');
  if (document.pointerLockElement === canvas) document.exitPointerLock();
}

function showGameOver(title, reason) {
  game.state = 'gameover';
  const acc = game.shots ? Math.round((game.hits / game.shots) * 100) : 0;
  el.goTitle.textContent = title;
  el.goReason.textContent = reason;
  el.goKills.textContent = String(game.kills);
  el.goHeads.textContent = String(game.headshots);
  el.goAcc.textContent = `${acc}%`;
  el.goRound.textContent = String(game.round);
  el.goMoney.textContent = `$${game.money}`;
